<script>
 import { computeEigenCovarianceLesson } from '@/lib/formula-lessons/eigen-covariance.mjs';
 export let lesson; export let spec;
 let x1=spec.x[0],x2=spec.x[1]; $: x=[Number(x1),Number(x2)]; $: r=computeEigenCovarianceLesson({A:spec.A,x,points:spec.points}); const f=(v,d=4)=>Number(v).toFixed(d);
</script>
<div class="grid" data-eigen-covariance-lesson data-focus={lesson.focus}><section class="panel"><p class="eyebrow">Quadratic form and eigensystem</p><h6>xᵀAx={f(r.quadratic)}</h6>{#each r.eigen.values as value,i (i)}<div class="eig"><strong>λ{i+1}={f(value)}</strong><span>v=[{r.eigen.vectors[i].map(v=>f(v)).join(', ')}]</span></div>{/each}<div class="check">tr(A)−Σλ={f(r.traceEigenResidual,8)} · det(A)−Πλ={f(r.detEigenResidual,8)}</div></section><section class="panel"><p class="eyebrow">Covariance → principal axes</p><div class="matrix">mean=[{r.covariance.mean.map(v=>f(v)).join(', ')}]<br/>C=[{r.covariance.covariance.map(row=>`[${row.map(v=>f(v)).join(', ')}]`).join(', ')}]<br/>PCA eigenvalues=[{r.covarianceEigen.values.map(v=>f(v)).join(', ')}]</div><label>x₁ <output>{f(x1,2)}</output><input bind:value={x1} type="range" min="-2" max="2" step="0.05"/></label><label>x₂ <output>{f(x2,2)}</output><input bind:value={x2} type="range" min="-2" max="2" step="0.05"/></label></section></div>
<style>.grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}h6{margin:.25rem 0 .7rem}.eig,.matrix,.check{border-radius:.7rem;background:var(--color-muted);padding:.65rem;margin:.45rem 0;font-size:.72rem}.eig{display:flex;justify-content:space-between;gap:.5rem}.panel label{display:grid;grid-template-columns:1fr auto;gap:.2rem;margin-top:.6rem;font-size:.73rem;font-weight:800}.panel input{grid-column:1/-1;min-height:30px}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style>
